package me.dylmye.isa.ui.help

/**
 * A help topic the Help tab lists as a card.
 *
 * [id] is the filename of the article in `app/src/main/assets/help`, and [title] is its `# `
 * heading. Both the topic list and each topic's copy are generated by
 * `scripts/generate-help.mjs`, so an article and its card cannot disagree.
 */
internal data class HelpTopic(val id: String, val title: String)
